package com.bidx.repository; import com.bidx.util.*;import org.w3c.dom.*;import java.nio.file.*;import java.util.*;
public class WatchlistRepository {private final Path p=AppPaths.file("watchlists.xml");public synchronized Set<String> forUser(String id){Document d=XmlStore.load(p,"watchlists");Set<String>s=new HashSet<>();NodeList n=d.getElementsByTagName("watch");for(int i=0;i<n.getLength();i++){Element e=(Element)n.item(i);if(XmlStore.text(e,"userId").equals(id))s.add(XmlStore.text(e,"auctionId"));}return s;}public synchronized void toggle(String user,String auction){Document d=XmlStore.load(p,"watchlists");NodeList n=d.getElementsByTagName("watch");for(int i=0;i<n.getLength();i++){Element e=(Element)n.item(i);if(XmlStore.text(e,"userId").equals(user)&&XmlStore.text(e,"auctionId").equals(auction)){e.getParentNode().removeChild(e);XmlStore.save(d,p);return;}}Element e=d.createElement("watch");XmlStore.put(d,e,"userId",user);XmlStore.put(d,e,"auctionId",auction);XmlStore.put(d,e,"createdAt",java.time.LocalDateTime.now());d.getDocumentElement().appendChild(e);XmlStore.save(d,p);}}
